import java.util.Scanner;
public class PythagoreanTheorem1 {
	public static void main(String[] args) {
		//Paso 1: Recibir los valores de cada lado de un triangulo rectangulo
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese la longitud del lado A:");
		double sideA = scan.nextDouble();
		System.out.println("Ingrese la longitud del lado B:");
		double sideB = scan.nextDouble();
		scan.close();
		//Paso 2: Calcular el cuadrado del lado A
		double squareSideA = Math.pow(sideA, 2);
		//Paso 3: Calcular el cuadrado del lado B
		double squareSideB = Math.pow(sideB, 2);
		//Paso 4: Usar el teorema de Pitagoras para calcular la longitud de la hipotenusa del triangulo
		double hypotenuse = Math.sqrt(squareSideA + squareSideB);
		//Paso 5: Imprimir el resultado
		System.out.println("Dado que el lado A es " + sideA + " y el lado B es " + sideB + ", la hipotenusa es " + hypotenuse);
	}
}

